package common_persistence

import (
	"bytes"
	"context"
	"database/sql"
	"errors"
	"sort"
	"time"

	"github.com/Suhaibinator/SRouter/pkg/scontext"
	models "github.com/Suhaibinator/go-common/pkg/common_persistence/common_persistence_models"
	"github.com/Suhaibinator/go-common/pkg/config"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
)

var (
	ErrNotificationEmissionConflict    = errors.New("notification emission source already has different content or audience")
	ErrNotificationEmissionTransaction = errors.New("notification emission staging requires its original source transaction")
)

const (
	NotificationEmissionPending   = "pending"
	NotificationEmissionCompleted = "completed"
	NotificationEmissionCancelled = "cancelled"
	NotificationEmissionExhausted = "exhausted"
)

// NotificationEmissionProgress is committed with the callback's inbox writes.
// A terminal first snapshot page may also consume its first materialization batch.
type NotificationEmissionProgress struct {
	Recipients       []models.NotificationEmissionRecipient
	Cursor           []byte
	SnapshotDone     bool
	ProcessedUserIDs []uint64
	Accepted         uint64
}

type NotificationFanoutBacklog struct {
	PendingCount     uint64
	OldestPendingAge time.Duration
	// CountSaturated means PendingCount is a lower bound, not an exact count.
	CountSaturated bool
}

// notificationEmissionUpdate keeps SQL clock expressions typed while Select
// lists make each transition's zero-value and NULL assignments explicit.
type notificationEmissionUpdate struct {
	Fingerprint                    string
	State                          string
	Attempts                       uint32
	DueAt                          clause.Expr `gorm:"type:timestamptz"`
	LastError                      string
	LeaseOwner                     string
	LeaseToken                     string
	LeaseExpiresAt                 *time.Time
	AudienceSize                   uint64
	Cursor                         []byte `gorm:"type:bytea"`
	SnapshotReady                  bool
	SourceSnapshotSnapshot         string `gorm:"column:source_snapshot_snapshot"`
	SourceSnapshotUpperBound       string `gorm:"column:source_snapshot_upper_bound;type:xid8"`
	SourceSnapshotEpoch            uint64 `gorm:"column:source_snapshot_epoch"`
	SourceSnapshotSystemIdentifier string `gorm:"column:source_snapshot_system_identifier"`
	Processed                      uint64
	Accepted                       uint64
	CompletedAt                    clause.Expr `gorm:"type:timestamptz"`
	Payload                        []byte      `gorm:"type:bytea"`
	FallbackText                   string
	CompactedAt                    clause.Expr `gorm:"type:timestamptz"`
	UpdatedAt                      time.Time
}

func (s *GormNotificationStore[U]) EnqueueNotificationEmission(ctx context.Context, in models.NotificationEmission) (*models.NotificationEmission, bool, error) {
	if tx, ok := scontext.GetTransaction(ctx); !ok || tx == nil {
		return nil, false, ErrNotificationEmissionTransaction
	}
	if in.Producer == "" || len(in.Producer) > config.MaxNotificationProducerBytes || in.OrganizationID < 0 || in.Type == 0 || in.SourceKey == "" || len(in.SourceKey) > config.MaxNotificationSourceKeyBytes || len(in.EmissionKey) > config.MaxNotificationEmissionKeyBytes || in.OperationID == "" || len(in.OperationID) > config.MaxNotificationOperationIDBytes || len(in.Payload) > config.MaxNotificationPayloadBytes || len(in.FallbackText) > config.MaxNotificationFallbackTextBytes || len(in.TraceID) > config.MaxNotificationTraceIDBytes {
		return nil, false, ErrNotificationInput
	}
	var job models.NotificationEmission
	var created bool
	err := s.WithTransaction(ctx, func(ctx context.Context) error {
		stamp, snapshot, err := s.CaptureNotificationTransaction(ctx)
		if err != nil {
			return err
		}
		now := time.Now().UTC()
		if in.SourceTime.IsZero() {
			in.SourceTime = now
		}
		// DueAt is generated by PostgreSQL; process clock skew must not delay an
		// immediately accepted emission or make its later lease expire early.
		job = models.NotificationEmission{Producer: in.Producer, OrganizationID: in.OrganizationID, Type: in.Type, SourceKey: in.SourceKey, EmissionKey: in.EmissionKey, OperationID: in.OperationID, Event: in.Event, Payload: in.Payload, FallbackText: in.FallbackText, SourceTime: in.SourceTime, TraceID: in.TraceID, SourceStamp: stamp, SourceSnapshot: snapshot, State: NotificationEmissionPending, SnapshotReady: !in.Event}
		if !in.Event {
			job.SourceSnapshot = models.NotificationVisibilitySnapshot{}
		}
		db := s.db.DB(ctx)
		res := db.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "producer"}, {Name: "organization_id"}, {Name: "type"}, {Name: "source_key"}, {Name: "emission_key"}}, DoNothing: true}).Create(&job)
		if res.Error != nil {
			return res.Error
		}
		created = res.RowsAffected == 1
		if created {
			return nil
		}
		// PostgreSQL's unique-index wait is intentional. The other operation's
		// committed fingerprint is compared only when our full manifest is known.
		return db.Where("producer = ? AND organization_id = ? AND type = ? AND source_key = ? AND emission_key = ?", in.Producer, in.OrganizationID, in.Type, in.SourceKey, in.EmissionKey).Take(&job).Error
	})
	if err != nil {
		return nil, false, err
	}
	return &job, created, nil
}

func validateEmissionRecipients(recipients []models.NotificationEmissionRecipient) error {
	if len(recipients) > config.MaxNotificationFanoutBatchRecipients {
		return ErrNotificationInput
	}
	// The cumulative byte budget is the service's hot
	// notification_emit_max_total_bytes, charged per input before any write;
	// only the per-value ceilings are rechecked here.
	for _, r := range recipients {
		if r.UserID == 0 || len(r.Payload) > config.MaxNotificationPayloadBytes || len(r.FallbackText) > config.MaxNotificationFallbackTextBytes || len(r.Metadata) > config.MaxNotificationMetadataBytes || !validDeliveryTag(r.DeliveryTag) {
			return ErrNotificationInput
		}
	}
	return nil
}

func insertEmissionRecipients(db *gorm.DB, id uint64, recipients []models.NotificationEmissionRecipient) (int64, error) {
	if err := validateEmissionRecipients(recipients); err != nil {
		return 0, err
	}
	if len(recipients) == 0 {
		return 0, nil
	}
	rows := append([]models.NotificationEmissionRecipient(nil), recipients...)
	for i := range rows {
		rows[i].EmissionID = id
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].UserID < rows[j].UserID })
	res := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&rows)
	return res.RowsAffected, res.Error
}

func (s *GormNotificationStore[U]) AppendNotificationEmissionRecipients(ctx context.Context, id uint64, operationID string, recipients []models.NotificationEmissionRecipient) error {
	if tx, ok := scontext.GetTransaction(ctx); !ok || tx == nil {
		return ErrNotificationEmissionTransaction
	}
	if id == 0 || operationID == "" {
		return ErrNotificationInput
	}
	if err := validateEmissionRecipients(recipients); err != nil {
		return err
	}
	return s.WithTransaction(ctx, func(ctx context.Context) error {
		db := s.db.DB(ctx)
		var job models.NotificationEmission
		if err := db.Take(&job, id).Error; err != nil {
			return err
		}
		if job.OperationID != operationID {
			return nil
		}
		identity, err := s.CurrentNotificationIdentity(ctx)
		if err != nil {
			return err
		}
		// An earlier operation's audience is immutable. Do not acquire its row
		// lock while visiting chunk inputs; Finalize locks those IDs in order.
		if err := db.Where("source_xid = pg_current_xact_id() AND source_epoch = ? AND source_system_identifier = ?", identity.Epoch, identity.SystemIdentifier).Clauses(clause.Locking{Strength: "UPDATE"}).Take(&job, id).Error; err != nil {
			if errors.Is(err, gorm.ErrRecordNotFound) {
				return ErrNotificationEmissionTransaction
			}
			return err
		}
		if job.Fingerprint != "" || job.Event {
			return ErrNotificationEmissionConflict
		}
		// Operation-local duplicates may agree but must never silently replace content.
		ids := make([]uint64, 0, len(recipients))
		for _, r := range recipients {
			ids = append(ids, r.UserID)
		}
		var old []models.NotificationEmissionRecipient
		if len(ids) > 0 {
			if err := db.Where("emission_id = ? AND user_id IN ?", id, ids).Find(&old).Error; err != nil {
				return err
			}
		}
		seen := make(map[uint64]models.NotificationEmissionRecipient, len(old)+len(recipients))
		for _, r := range old {
			seen[r.UserID] = r
		}
		for _, r := range recipients {
			if previous, ok := seen[r.UserID]; ok && (previous.Override != r.Override || previous.FallbackText != r.FallbackText || previous.DeliveryTag != r.DeliveryTag || !bytes.Equal(previous.Payload, r.Payload) || !bytes.Equal(previous.Metadata, r.Metadata)) {
				return ErrNotificationEmissionConflict
			}
			seen[r.UserID] = r
		}
		count, err := insertEmissionRecipients(db, id, recipients)
		if err != nil {
			return err
		}
		return db.Model(&models.NotificationEmission{}).Where("id = ?", id).UpdateColumn("audience_size", gorm.Expr("audience_size + ?", count)).Error
	})
}

func (s *GormNotificationStore[U]) FinalizeNotificationEmission(ctx context.Context, id uint64, operationID, fingerprint string) (*models.NotificationEmission, error) {
	if tx, ok := scontext.GetTransaction(ctx); !ok || tx == nil {
		return nil, ErrNotificationEmissionTransaction
	}
	if id == 0 || operationID == "" || len(fingerprint) != 64 {
		return nil, ErrNotificationInput
	}
	var job models.NotificationEmission
	err := s.WithTransaction(ctx, func(ctx context.Context) error {
		db := s.db.DB(ctx)
		settled := func() (bool, error) {
			if job.OperationID != operationID || job.Fingerprint != "" {
				if job.Fingerprint != fingerprint {
					return true, ErrNotificationEmissionConflict
				}
				return true, nil
			}
			return false, nil
		}
		// A finalized fingerprint is immutable and only the owning operation can
		// finalize, so a non-owner compares without queueing behind a worker's
		// row lock on the emission.
		if err := db.Take(&job, id).Error; err != nil {
			return err
		}
		if done, err := settled(); done {
			return err
		}
		if err := db.Clauses(clause.Locking{Strength: "UPDATE"}).Take(&job, id).Error; err != nil {
			return err
		}
		if done, err := settled(); done {
			return err
		}
		identity, err := s.CurrentNotificationIdentity(ctx)
		if err != nil {
			return err
		}
		updates := notificationEmissionUpdate{Fingerprint: fingerprint}
		columns := []string{"fingerprint"}
		if job.SnapshotReady && job.AudienceSize == 0 {
			updates.State = NotificationEmissionCompleted
			updates.CompletedAt = gorm.Expr("clock_timestamp()")
			columns = append(columns, "state", "completed_at")
		}
		res := db.Model(&job).Where("source_xid = pg_current_xact_id() AND source_epoch = ? AND source_system_identifier = ?", identity.Epoch, identity.SystemIdentifier).Clauses(clause.Returning{}).Select(columns).Updates(updates)
		if res.Error != nil {
			return res.Error
		}
		if res.RowsAffected != 1 {
			return ErrNotificationEmissionTransaction
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	s.queueChanged(ctx, NotificationQueueFanout)
	return &job, nil
}

func (s *GormNotificationStore[U]) GetNotificationEmission(ctx context.Context, id uint64) (*models.NotificationEmission, error) {
	var job models.NotificationEmission
	err := s.db.DB(ctx).Take(&job, id).Error
	if errors.Is(err, gorm.ErrRecordNotFound) {
		return nil, nil
	}
	return &job, err
}

func (s *GormNotificationStore[U]) RetryNotificationEmission(ctx context.Context, id uint64) (bool, error) {
	updates := notificationEmissionUpdate{State: NotificationEmissionPending, DueAt: gorm.Expr("clock_timestamp()")}
	res := s.db.DB(ctx).Model(&models.NotificationEmission{}).Where("id = ? AND state = ?", id, NotificationEmissionExhausted).
		Select("state", "attempts", "due_at", "last_error", "lease_owner", "lease_token", "lease_expires_at").Updates(updates)
	if res.Error == nil && res.RowsAffected == 1 {
		s.queueChanged(ctx, NotificationQueueFanout)
	}
	return res.RowsAffected == 1, res.Error
}

func (s *GormNotificationStore[U]) ClaimNotificationEmissions(ctx context.Context, owner string, lease time.Duration, limit int, maxAttempts uint32) ([]models.NotificationEmission, error) {
	if owner == "" || lease <= 0 || limit < 1 || limit > config.MaxNotificationFanoutWorkerCount || maxAttempts < 1 || maxAttempts > config.MaxNotificationFanoutMaxAttempts {
		return nil, ErrNotificationInput
	}
	// Candidate selection and SKIP LOCKED must be one statement: selecting a
	// LIMIT first would hand concurrent claimers the same rows, and every
	// claimer after the first would get an empty batch while backlog exists.
	// SKIP LOCKED never waits, so due-order locking cannot deadlock with
	// source resolution's ID-order locks. Rows already at maxAttempts are
	// exhausted instead of leased; every leased row gets its own token and an
	// expiry from one database clock sample.
	var jobs []models.NotificationEmission
	err := s.db.DB(ctx).Raw(`WITH now AS (SELECT clock_timestamp() AS t),
picked AS (
	SELECT id FROM gocommon_notification_emissions
	WHERE state = @pending AND due_at <= clock_timestamp() AND (lease_expires_at IS NULL OR lease_expires_at <= clock_timestamp()) AND fingerprint <> ''
	ORDER BY due_at, id LIMIT @limit FOR UPDATE SKIP LOCKED
),
claimed AS (
	UPDATE gocommon_notification_emissions e SET
		state = CASE WHEN e.attempts >= @max THEN @exhausted ELSE e.state END,
		last_error = CASE WHEN e.attempts >= @max THEN 'attempts_exhausted' ELSE e.last_error END,
		attempts = CASE WHEN e.attempts >= @max THEN e.attempts ELSE e.attempts + 1 END,
		lease_owner = CASE WHEN e.attempts >= @max THEN '' ELSE @owner END,
		lease_token = CASE WHEN e.attempts >= @max THEN '' ELSE gen_random_uuid()::text END,
		lease_expires_at = CASE WHEN e.attempts >= @max THEN NULL ELSE now.t + @lease * interval '1 microsecond' END
	FROM picked, now WHERE e.id = picked.id
	RETURNING e.*
)
SELECT * FROM claimed ORDER BY due_at, id`,
		sql.Named("pending", NotificationEmissionPending), sql.Named("exhausted", NotificationEmissionExhausted),
		sql.Named("limit", limit), sql.Named("max", maxAttempts), sql.Named("owner", owner), sql.Named("lease", lease.Microseconds()),
	).Scan(&jobs).Error
	return jobs, err
}

func emissionLease(db *gorm.DB, job models.NotificationEmission) *gorm.DB {
	return db.Where("id = ? AND state = ? AND lease_owner = ? AND lease_token = ? AND attempts = ? AND lease_expires_at > clock_timestamp()", job.ID, NotificationEmissionPending, job.LeaseOwner, job.LeaseToken, job.Attempts)
}

func (s *GormNotificationStore[U]) ListNotificationEmissionRecipients(ctx context.Context, id uint64, limit int) ([]models.NotificationEmissionRecipient, error) {
	if id == 0 || limit < 1 || limit > config.MaxNotificationFanoutBatchRecipients {
		return nil, ErrNotificationInput
	}
	var rows []models.NotificationEmissionRecipient
	err := s.db.DB(ctx).Where("emission_id = ?", id).Order("user_id").Limit(limit).Find(&rows).Error
	return rows, err
}

func (s *GormNotificationStore[U]) AdvanceNotificationEmission(ctx context.Context, claim models.NotificationEmission, step func(context.Context, *models.NotificationEmission) (NotificationEmissionProgress, error)) (*models.NotificationEmission, error) {
	if claim.ID == 0 || claim.LeaseToken == "" || step == nil {
		return nil, ErrNotificationInput
	}
	_, ambient := scontext.GetTransaction(ctx)
	var job models.NotificationEmission
	err := s.WithTransaction(ctx, func(ctx context.Context) error {
		db := s.db.DB(ctx)
		if !ambient {
			// The step's plain membership reads run after this row lock may have
			// waited; each statement needs a fresh snapshot so a leave or ban
			// committed meanwhile is seen, whatever default_transaction_isolation is.
			if err := db.Exec("SET TRANSACTION ISOLATION LEVEL READ COMMITTED").Error; err != nil {
				return err
			}
		}
		if err := emissionLease(db, claim).Clauses(clause.Locking{Strength: "UPDATE"}).Take(&job).Error; err != nil {
			if errors.Is(err, gorm.ErrRecordNotFound) {
				return ErrNotificationLeaseLost
			}
			return err
		}
		callbackJob := job
		progress, err := step(ctx, &callbackJob)
		if err != nil {
			return err
		}
		if len(progress.ProcessedUserIDs) > config.MaxNotificationFanoutBatchRecipients || progress.Accepted > uint64(len(progress.ProcessedUserIDs)) || len(progress.Cursor) > config.MaxNotificationProducerCursorBytes {
			return ErrNotificationInput
		}
		updates := notificationEmissionUpdate{DueAt: gorm.Expr("clock_timestamp()")}
		columns := []string{"attempts", "last_error", "lease_owner", "lease_token", "lease_expires_at", "due_at", "processed", "accepted"}
		audience := job.AudienceSize
		if !job.SnapshotReady {
			if !progress.SnapshotDone && (len(progress.Recipients) == 0 || len(progress.Cursor) == 0 || bytes.Equal(progress.Cursor, job.Cursor)) {
				return ErrNotificationInput
			}
			if !progress.SnapshotDone && len(progress.ProcessedUserIDs) > 0 {
				return ErrNotificationInput
			}
			inserted, err := insertEmissionRecipients(db, job.ID, progress.Recipients)
			if err != nil {
				return err
			}
			if !progress.SnapshotDone && inserted == 0 {
				// Advancing an opaque cursor without adding a candidate cannot
				// indefinitely refund attempts for a cycling producer.
				return ErrNotificationInput
			}
			audience += uint64(inserted)
			updates.AudienceSize = audience
			updates.Cursor = progress.Cursor
			columns = append(columns, "audience_size", "cursor")
			if progress.SnapshotDone {
				updates.SnapshotReady = true
				updates.SourceSnapshotUpperBound = "0"
				columns = append(columns, "snapshot_ready", "source_snapshot_snapshot", "source_snapshot_upper_bound", "source_snapshot_epoch", "source_snapshot_system_identifier")
			}
		} else if len(progress.Recipients) > 0 || progress.SnapshotDone {
			return ErrNotificationInput
		}
		processed := uint64(len(progress.ProcessedUserIDs))
		if processed > 0 {
			res := db.Where("emission_id = ? AND user_id IN ?", job.ID, progress.ProcessedUserIDs).Delete(&models.NotificationEmissionRecipient{})
			if res.Error != nil {
				return res.Error
			}
			if uint64(res.RowsAffected) != processed {
				return ErrNotificationInput
			}
		}
		updates.Processed = job.Processed + processed
		updates.Accepted = job.Accepted + progress.Accepted
		if job.Processed+processed > audience {
			return ErrNotificationInput
		}
		if (job.SnapshotReady || progress.SnapshotDone) && job.Processed+processed == audience {
			updates.State = NotificationEmissionCompleted
			updates.CompletedAt = gorm.Expr("clock_timestamp()")
			columns = append(columns, "state", "completed_at")
		}
		if job.SnapshotReady && processed == 0 && job.Processed < audience {
			return ErrNotificationInput
		}
		res := emissionLease(db.Model(&job), claim).Clauses(clause.Returning{}).Select(columns).Updates(updates)
		if res.Error != nil {
			return res.Error
		}
		if res.RowsAffected != 1 {
			return ErrNotificationLeaseLost
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return &job, nil
}

func (s *GormNotificationStore[U]) FinishNotificationEmissionAttempt(ctx context.Context, job models.NotificationEmission, deferAttempt bool, reason string, retryAfter time.Duration, maxAttempts uint32) error {
	if maxAttempts < 1 || maxAttempts > config.MaxNotificationFanoutMaxAttempts {
		return ErrNotificationInput
	}
	switch reason {
	case "disabled", "shutdown", "type_unavailable", "producer_unavailable":
		if !deferAttempt {
			return ErrNotificationInput
		}
	case "step_failed":
		if deferAttempt {
			return ErrNotificationInput
		}
	default:
		return ErrNotificationInput
	}
	if retryAfter < 0 {
		return ErrNotificationInput
	}
	state, attempts := NotificationEmissionPending, job.Attempts
	if deferAttempt {
		if attempts > 0 {
			attempts--
		}
	} else if attempts >= maxAttempts {
		state = NotificationEmissionExhausted
	}
	updates := notificationEmissionUpdate{State: state, Attempts: attempts, LastError: reason, DueAt: gorm.Expr("clock_timestamp() + (? * interval '1 microsecond')", retryAfter.Microseconds())}
	res := emissionLease(s.db.DB(ctx).Model(&models.NotificationEmission{}), job).
		Select("state", "attempts", "last_error", "due_at", "lease_owner", "lease_token", "lease_expires_at").Updates(updates)
	if res.Error != nil {
		return res.Error
	}
	if res.RowsAffected != 1 {
		return ErrNotificationLeaseLost
	}
	s.queueChanged(ctx, NotificationQueueFanout)
	return nil
}

func (s *GormNotificationStore[U]) cancelNotificationEmissionsForSource(ctx context.Context, organizationID int64, typeID uint32, sourceKey string) error {
	db := s.db.DB(ctx)
	var jobs []models.NotificationEmission
	open := []string{NotificationEmissionPending, NotificationEmissionExhausted}
	// Terminal emissions are immutable, so only open ones are locked.
	if err := db.Select("id").Clauses(clause.Locking{Strength: "UPDATE"}).Where("organization_id = ? AND type = ? AND source_key = ? AND state IN ?", organizationID, typeID, sourceKey, open).Order("id").Find(&jobs).Error; err != nil {
		return err
	}
	if len(jobs) == 0 {
		return nil
	}
	ids := make([]uint64, len(jobs))
	for i, j := range jobs {
		ids[i] = j.ID
	}
	var cancelled []models.NotificationEmission
	updates := notificationEmissionUpdate{State: NotificationEmissionCancelled, CompletedAt: gorm.Expr("clock_timestamp()")}
	if err := db.Model(&cancelled).Clauses(clause.Returning{Columns: []clause.Column{{Name: "id"}}}).Where("id IN ? AND state IN ?", ids, open).
		Select("state", "lease_owner", "lease_token", "lease_expires_at", "completed_at").Updates(updates).Error; err != nil {
		return err
	}
	if len(cancelled) == 0 {
		return nil
	}
	ids = ids[:0]
	for _, j := range cancelled {
		ids = append(ids, j.ID)
	}
	// Cancelled work is never materialized; its recipient rows are dead weight.
	return db.Where("emission_id IN ?", ids).Delete(&models.NotificationEmissionRecipient{}).Error
}

// NotificationFanoutBacklog counts at most limit pending emissions; a larger
// backlog reports limit with CountSaturated set. The caller samples limit from
// notification_fanout_backlog_count_limit.
func (s *GormNotificationStore[U]) NotificationFanoutBacklog(ctx context.Context, now time.Time, limit int) (NotificationFanoutBacklog, error) {
	if limit < config.MinNotificationFanoutBacklogCountLimit || limit > config.MaxNotificationFanoutBacklogCountLimit {
		return NotificationFanoutBacklog{}, ErrNotificationInput
	}
	var result struct {
		Count  uint64
		Oldest *time.Time
	}
	err := s.db.DB(ctx).Raw(`SELECT count(*) AS count, min(created_at) AS oldest FROM (
		SELECT created_at FROM gocommon_notification_emissions
		WHERE state = 'pending' AND fingerprint <> '' ORDER BY created_at LIMIT ?
	) pending`, limit+1).Scan(&result).Error
	out := NotificationFanoutBacklog{PendingCount: min(result.Count, uint64(limit)), CountSaturated: result.Count > uint64(limit)}
	if result.Oldest != nil && now.After(*result.Oldest) {
		out.OldestPendingAge = now.Sub(*result.Oldest)
	}
	return out, err
}

func (s *GormNotificationStore[U]) CompactNotificationEmissions(ctx context.Context, before time.Time, limit int) (int64, error) {
	if limit < 1 || limit > config.MaxNotificationFanoutCompactionBatch {
		return 0, ErrNotificationInput
	}
	var count int64
	err := s.WithTransaction(ctx, func(ctx context.Context) error {
		db := s.db.DB(ctx)
		var locked bool
		if err := db.Raw("SELECT pg_try_advisory_xact_lock(hashtextextended(?, 0))", "go-common:notification-fanout:compaction").Scan(&locked).Error; err != nil {
			return err
		}
		if !locked {
			return nil
		}
		var jobs []models.NotificationEmission
		if err := db.Raw(`WITH candidates AS MATERIALIZED (
			SELECT id FROM gocommon_notification_emissions
			WHERE state IN ('completed', 'cancelled') AND compacted_at IS NULL AND completed_at < ?
			ORDER BY completed_at, id LIMIT ?
		) SELECT e.id FROM gocommon_notification_emissions e JOIN candidates c ON c.id = e.id
		ORDER BY e.id FOR UPDATE OF e SKIP LOCKED`, before, limit).Scan(&jobs).Error; err != nil {
			return err
		}
		if len(jobs) == 0 {
			return nil
		}
		ids := make([]uint64, len(jobs))
		for i, j := range jobs {
			ids[i] = j.ID
		}
		if err := db.Where("emission_id IN ?", ids).Delete(&models.NotificationEmissionRecipient{}).Error; err != nil {
			return err
		}
		updates := notificationEmissionUpdate{SourceSnapshotUpperBound: "0", CompactedAt: gorm.Expr("clock_timestamp()")}
		res := db.Model(&models.NotificationEmission{}).Where("id IN ?", ids).
			Select("payload", "fallback_text", "cursor", "source_snapshot_snapshot", "source_snapshot_upper_bound", "source_snapshot_epoch", "source_snapshot_system_identifier", "compacted_at").Updates(updates)
		count = res.RowsAffected
		return res.Error
	})
	return count, err
}
